<script lang="ts">
 import CardFace from '$lib/cards/CardFace.svelte';
 import {cardById} from './cards';
 import {supportedTechnologyActions,technologyActionBlocker,technologyActionLocation,technologyActionTerms,permittedActionShipyards} from './technology-actions';
 import type {PublicSetup} from './setup';
 import type {TurnMove} from './turn';
 let {game,compact=false,busy,allowed,send,inspect}:{game:PublicSetup;compact?:boolean;busy:boolean;allowed:boolean;send:(move:TurnMove)=>void;inspect:(id:string)=>void}=$props();
 const actor=$derived(game.players.find(p=>p.position===game.activePosition)!);
 const publicChoices=$derived(game.technologies.filter(t=>supportedTechnologyActions[t.card]));
 let chosen=$state(''),destination=$state('sol');
 const id=$derived(publicChoices.find(t=>t.card===chosen)?.card??publicChoices.find(t=>actor.research.includes(t.card))?.card??publicChoices[0]?.card);
 const card=$derived(id?cardById(id):undefined);
 const action=$derived(id?supportedTechnologyActions[id][0]:0);
 const terms=$derived(id?technologyActionTerms(game,id,action):undefined);
 const blocker=$derived(id?technologyActionBlocker(game,id,action):'No printed technology Action is available.');
 const preparing=$derived(!blocker&&!game.discovery?.powerReady);
 const shipBuild=$derived(!!id&&['narrow-beam-lasers','plasma-cannon','human-experiments','android-destroyers'].includes(id));
 const occupant=$derived(id?game.players.find(p=>p.actionLocation===technologyActionLocation(id,action,0)):undefined);
</script>
<section class="technology-action-plan" class:compact aria-label="Printed technology action plan" aria-busy={busy||preparing}>
 <nav aria-label="Public technology actions"><button aria-label="Previous technology Action" onclick={()=>{const index=publicChoices.findIndex(t=>t.card===id);chosen=publicChoices[(index+publicChoices.length-1)%publicChoices.length].card;destination='sol';}}>←</button><span aria-live="polite">Public Actions · {publicChoices.findIndex(t=>t.card===id)+1} / {publicChoices.length}<small>{card?.title??'Browse revealed technologies'}</small></span><button aria-label="Next technology Action" onclick={()=>{const index=publicChoices.findIndex(t=>t.card===id);chosen=publicChoices[(index+1)%publicChoices.length].card;destination='sol';}}>→</button></nav>
 {#if card&&id&&terms}<div class="action-object"><button class="face" aria-label={`Inspect printed actions on ${card.title}`} onclick={()=>inspect(id)}><CardFace {card} presentation={{researchers:game.players.filter(p=>p.research.includes(id)).map(p=>p.name),actionOccupant:occupant?.name}}/></button><div class="printed-action"><h3>{card.title}</h3><p class="ownership">{actor.name} · {actor.research.includes(id)?'Research cube placed':'No research cube here'}{#if compact}<span class="compact-occupancy"> · {occupant?`${occupant.name}’s Action pawn`:'Open Action space'}</span>{/if}</p><div class="ivory-rule"><strong>Printed Action {action+1}</strong><p>{terms.section.text}</p><span>{terms.section.cost??'No resource payment printed'}</span></div><div class="pawn-space" role="group" aria-label={`Technology Action space ${card.title}`}><span aria-hidden="true">{occupant?'♟':'◇'}</span><strong>{occupant?`${occupant.name}’s Action pawn`:'Open Action space'}</strong></div>{#if shipBuild}<label>Build at your shipyard<select bind:value={destination}>{#each permittedActionShipyards(game) as location}<option value={location}>{location==='sol'?'Sol':location.replace('shipyard-','Shipyard ')}</option>{/each}</select></label>{/if}</div></div>
 <div class="commit-action"><div><strong>{card.title}</strong><p id="technology-action-reason">{#if blocker}{blocker}{:else if preparing}Preparing the public board…{:else if compact}{terms.ore?`Pay ${terms.ore} Ore · `:''}{terms.population?`${terms.population} Population · `:''}Resolve the printed Action.{:else}{terms.ore?`Pay ${terms.ore} Ore. `:''}{terms.population?`Use ${terms.population} Population through the printed effect. `:''}Move your Action pawn; resolve every effect before production.{/if}</p></div><button class="primary" aria-describedby="technology-action-reason" disabled={busy||!allowed||!!blocker||preparing} onclick={()=>send({kind:'technology-action',card:id,action,space:0,...(shipBuild?{destination}:{})})}>Use {card.title} Action</button></div>
 {:else}<p>No revealed technology currently has an available printed Action.</p>{/if}
</section>
