358;border-radius:5px;font:14px 'Atkinson Hyperlegible',sans-serif}.commit-action{flex:none;display:flex;align-items:center;gap:16px;padding:12px;border:1px solid #b3a06c;border-radius:8px;background:#122c33}.commit-action>div{flex:1;min-width:0}.commit-action strong{font:600 21px 'Cormorant Garamond',serif}.commit-action p{font-size:13px;line-height:1.35;margin:5px 0}.primary{background:#15575a;max-width:43%}
@container(max-width:620px){nav{gap:5px}nav button{flex-basis:140px;font-size:12px;padding:7px}nav small{font-size:10px}.action-object{grid-template-columns:110px minmax(0,1fr);gap:10px}.printed-action h3{font-size:22px}.ownership{font-size:11px;margin-bottom:8px}.ivory-rule{padding:9px}.ivory-rule p{font-size:14px}.ivory-rule>span{font-size:12px}.pawn-space{gap:6px;font-size:12px;padding:7px}.commit-action{flex-wrap:wrap;gap:8px;padding:10px}.commit-action>div{width:100%;flex-basis:100%}.primary{max-width:none;width:100%}}
.compact{gap:6px}.compact nav button{flex-basis:125px;font-size:11px;padding:6px}.compact nav small{font-size:9px}.compact .action-object{grid-template-columns:105px minmax(0,1fr);gap:10px}.compact .printed-action h3{font-size:20px;line-height:1.1}.compact .ownership{font-size:10px;margin-bottom:5px}.compact .ivory-rule{padding:7px}.compact .ivory-rule p{font-size:12px;line-height:1.25;margin:5px 0}.compact .ivory-rule>span{font-size:10px;padding-top:5px}.compact .pawn-space{display:none;min-height:0;font-size:10px;padding:3px;margin:4px 0}.compact .pawn-space>span{font-size:18px}.compact label{font-size:10px;gap:3px}.compact select{font-size:11px;padding:5px}.compact .commit-action{flex-wrap:nowrap;gap:8px;padding:7px}.compact .commit-action>div{width:auto;flex-basis:auto}.compact .commit-action strong{font-size:16px}.compact .commit-action p{font-size:10px}.compact .primary{max-width:43%;width:auto;font-size:11px;padding:6px}

